class Solution:
    from collections import deque
    def check_expression(self, exp):
            if len(exp) & 1:
                return False
            stack = deque()
            for ch in exp:
                if ch == '(' or ch == '{' or ch == '[':
                    stack.append(ch)
                if ch == ')' or ch == '}' or ch == ']':
                    if not stack:
                        return False
                    top = stack.pop()
                if ((top == '(' and ch != ')') or ((top == '{' and ch != '}') or (top == 'mutpy' and ch != ']'))):
                        return False
            return not stack

class Solution:
    def permutation_coefficient(self, n, k):
            P = [[0 for i in range(k + 1)] 
                    for j in range(n + 1)] 
            for i in range(n + 1): 
                for j in range(min(i, k) + 1): 
                    if (j == 0): 
                        P[i][j] = 1
                    else: 
                        P[i][j] = P[i - 1][j] + ( 
                                j * P[i - 1][j - 1]) 
                if j <= k:
                        P[i][j + 1] = 0
            return P[n][k]

