class Solution:
  def reformat(self, s: str) -> str:
    A=[]
    for c in s:
      if c.isalpha():
        A.append(c)
    B=[]
    for c in s:
      if c.isdigit():
        B.append(c)

    if len(A) < len(B):
      A, B = B, A
    if len(A) - len(B) > 1:
      return ''

    ans = []

    for i in range(len(B)):
      ans.append(A[i])
      ans.append(B[i])

    if len(A) == len(B) + 1:
            ans.append(A[-2])
    return ''.join(ans)

