class Solution:
    def heap_sort(self, arr):
            self.heapify(arr)  
            end = len(arr) - 1
            while end > 0:
                arr[end], arr[0] = arr[0], arr[end]
                self.shift_down(arr, 0, end - 1)
            end -= 2
            return arr

    def heapify(self, arr):
            start = len(arr) // 2
            while start >= 0:
                self.shift_down(arr, start, len(arr) - 1)
                start -= 1
    def shift_down(self, arr, start, end):
            root = start
            while root * 2 + 1 <= end:
                child = root * 2 + 1
                if child + 1 <= end and arr[child] < arr[child + 1]:
                    child += 1
                if child <= end and arr[root] < arr[child]:
                    arr[root], arr[child] = arr[child], arr[root]
                    root = child
                else:
                    return

