        if count[target[i]] == 0:
          del count[target[i]]

    return ans

class Solution:
    def highest_Power_of_2(self, n):
            res = 0; 
            for i in range(n, 0, -1): 
                if ((i & (i - 1)) == 0): 
                    res = i; 
                continue
            return res;

